--- Cell ID: fetch-usd-eur ---
```javascript
const sources = [
  {
    name: 'open.er-api.com',
    url: 'https://open.er-api.com/v6/latest/USD',
    pick: (d) => d?.rates?.EUR,
  },
  {
    name: 'frankfurter.app',
    url: 'https://api.frankfurter.app/latest?from=USD&to=EUR',
    pick: (d) => d?.rates?.EUR,
  },
];

const errors = [];
for (const s of sources) {
  try {
    const res = await fetch(s.url);
    if (!res.ok) throw new Error('HTTP error');
    const data = await res.json();
    const rate = s.pick(data);
    if (typeof rate !== 'number' || !isFinite(rate)) throw new Error('Rate not found');
    return { rate_eur: rate, source_eur: s.name };
  } catch (err) {
    errors.push(s.name + ': ' + err.message);
  }
}
throw new Error('EUR sources failed');
```

